# ABOUTME: Bind guest media producers to fixed broker-issued artifact tickets.
# ABOUTME: Guards apply only in the allowed native tool invocation context.
import hashlib
import json
import os
from pathlib import Path
import stat

MAX_FILE = 64 * 1024 * 1024


def trusted_silero(instructions_root):
    """Match the entire command provider generated by identity.profiles.native_profile."""
    root = Path(instructions_root)
    if not root.is_absolute() or '..' in root.parts or any(c.isspace() for c in str(root)):
        raise ValueError('Invalid trusted instructions root')
    expected = {'type': 'command',
        'command': 'PYTHONPATH=' + str(root) + '/services/hermes /usr/bin/python3 '
                   '-s -P -B -m identity.synthesize --input {input_path} --output {output_path}',
        'output_format': 'ogg', 'voice_compatible': True, 'timeout': 200, 'max_text_length': 900}
    return lambda provider, config: provider == 'silero' and config == expected


def install(*, role, allowed, operation, broker_call, resolve_artifact, trusted_tts):
    from agent import provider_media
    from tools import tts_tool, browser_tool

    original_image = provider_media.save_bytes
    original_url = provider_media.save_url
    original_base = tts_tool._resolve_output_base
    original_single = tts_tool._text_to_speech_single
    original_tts = tts_tool.text_to_speech_tool
    original_capture = browser_tool._capture_vision_screenshot
    original_preroute = browser_tool._vision._lightpanda_vision_preroute
    tickets = {}

    def guest(name):
        if role() != 'guest':
            return False
        if not allowed(name):
            raise PermissionError('Guest generation outside tool invocation')
        return True

    def begin(kind):
        value = broker_call('generated.begin', {'kind': kind})
        if not isinstance(value, dict) or set(value) != {'ticket', 'path'}:
            raise PermissionError('Invalid generation ticket')
        return value

    def abort(ticket):
        try:
            broker_call('generated.abort', {'ticket': ticket['ticket']})
        except Exception:
            pass

    def finish(ticket):
        fd = os.open(ticket['path'], os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
        try:
            info = os.fstat(fd)
            if not stat.S_ISREG(info.st_mode) or info.st_uid != os.getuid() or info.st_nlink != 1 or not 0 < info.st_size <= MAX_FILE:
                raise PermissionError('Invalid generated file')
            digest = hashlib.sha256()
            size = 0
            while chunk := os.read(fd, 1024 * 1024):
                size += len(chunk)
                if size > MAX_FILE:
                    raise PermissionError('Generated file too large')
                digest.update(chunk)
            result = broker_call('generated.finish', {'ticket': ticket['ticket'], 'sizeBytes': size, 'sha256': digest.hexdigest()})
            value = resolve_artifact(result['artifactId'], operation())
            return Path(value['localPath'])
        finally:
            os.close(fd)

    def save_bytes(kind, raw, *, prefix, extension):
        if not guest('image_generate'):
            return original_image(kind, raw, prefix=prefix, extension=extension)
        if kind != 'generated/images' or extension.lower() != 'png' or not isinstance(raw, bytes) or not 0 < len(raw) <= MAX_FILE:
            raise PermissionError('Image generation denied')
        ticket = begin('image')
        try:
            fd = os.open(ticket['path'], os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
            with os.fdopen(fd, 'wb') as target:
                target.write(raw)
            return finish(ticket)
        finally:
            abort(ticket)

    def save_url(*args, **kwargs):
        if role() == 'guest':
            raise PermissionError('Guest URL media denied')
        return original_url(*args, **kwargs)

    def resolve_base(output_path, provider, command_provider_config, want_opus):
        if not guest('text_to_speech'):
            return original_base(output_path, provider, command_provider_config, want_opus)
        if output_path or not trusted_tts(provider, command_provider_config):
            raise PermissionError('Guest TTS configuration denied')
        ticket = begin('audio')
        tickets[ticket['path']] = ticket
        return Path(ticket['path']), None

    def single(text, file_str, **kwargs):
        if not guest('text_to_speech'):
            return original_single(text, file_str, **kwargs)
        ticket = tickets.pop(file_str, None)
        if ticket is None or not isinstance(text, str) or not 0 < len(text) <= 900:
            if ticket:
                abort(ticket)
            raise PermissionError('Guest TTS denied')
        try:
            result = json.loads(original_single(text, file_str, **kwargs))
            if result.get('success') is not True or result.get('file_path') != file_str:
                raise PermissionError('Guest TTS output changed')
            alias = str(finish(ticket))
            result['file_path'] = alias
            result['media_tag'] = tts_tool._media_tag([alias], bool(result.get('voice_compatible')))
            return json.dumps(result)
        finally:
            abort(ticket)

    def speech(text, output_path=None, speed=None, instructions=None, provider=None):
        if not guest('text_to_speech'):
            return original_tts(text, output_path, speed, instructions, provider)
        from tools.tts_text_normalize import prepare_spoken_text
        if (not isinstance(text, str) or not 0 < len(text) <= 900 or output_path is not None
                or provider is not None):
            raise PermissionError('Guest TTS arguments denied')
        normalized = prepare_spoken_text(text, max_chars=None)
        if not normalized or len(normalized) > 900:
            raise PermissionError('Guest TTS text denied')
        return original_tts(text, output_path, speed, instructions, provider)

    def capture(task_id, annotate, screenshot_path, lp_prerouted):
        if not guest('browser_vision'):
            return original_capture(task_id, annotate, screenshot_path, lp_prerouted)
        if lp_prerouted:
            raise PermissionError('Guest browser fallback denied')
        ticket = begin('screenshot')
        path = Path(ticket['path'])
        try:
            if browser_tool._session.sandbox_screenshot_path(path):
                raise PermissionError('Guest browser sandbox denied')
            result, actual, error = original_capture(task_id, annotate, path, False)
            receipt_path = result.get('data', {}).get('path')
            if error is not None or not result.get('success') or actual != path or receipt_path not in (None, str(path)):
                raise PermissionError('Guest screenshot receipt mismatch')
            alias = finish(ticket)
            result.setdefault('data', {})['path'] = str(alias)
            return result, alias, None
        finally:
            abort(ticket)

    def preroute(task_id, annotate, screenshot_path):
        if not guest('browser_vision'):
            return original_preroute(task_id, annotate, screenshot_path)
        if browser_tool._vision._cloud._get_browser_engine() == 'lightpanda' or browser_tool._vision._cloud._get_cloud_provider() is not None:
            raise PermissionError('Guest browser fallback denied')
        return False, None, screenshot_path

    provider_media.save_bytes = save_bytes
    provider_media.save_url = save_url
    tts_tool._resolve_output_base = resolve_base
    tts_tool._text_to_speech_single = single
    tts_tool.text_to_speech_tool = speech
    browser_tool._capture_vision_screenshot = capture
    browser_tool._vision._lightpanda_vision_preroute = preroute
